import os,pathlib

def observe(client,bucket,key):
    rows=client.list_object_versions(Bucket=bucket,Prefix=key)
    def items(name):
        return [{'version_id':x['VersionId'],'is_latest':x['IsLatest']} for x in rows.get(name,[]) if x['Key']==key]
    return {'versions':items('Versions'),'delete_markers':items('DeleteMarkers')}

def backup(replica,bucket,key,approved_version,backup_path):
    response=replica.get_object(Bucket=bucket,Key=key,VersionId=approved_version)
    try:data=response['Body'].read()
    finally:response['Body'].close()
    with pathlib.Path(backup_path).open('wb')as out:
        out.write(data);out.flush();os.fsync(out.fileno())

def restore_version(authority,replica,bucket,key,approved_version,recovery_key):
    response=replica.get_object(Bucket=bucket,Key=key,VersionId=approved_version)
    try:data=response['Body'].read()
    finally:response['Body'].close()
    authority.put_object(Bucket=bucket,Key=recovery_key,Body=data)

def restore_backup(authority,backup_path,bucket,recovery_key):
    authority.put_object(Bucket=bucket,Key=recovery_key,Body=pathlib.Path(backup_path).read_bytes())

